mapper.select:
SELECT id, kb_id, user_id, role, granted_by, granted_at
FROM kb_member
WHERE kb_id = #{kbId} AND user_id = #{userId}

mapper.insert:
INSERT INTO kb_member (kb_id, user_id, role, granted_by)
VALUES (#{kbId}, #{userId}, #{role}, #{grantedBy})
ON CONFLICT (kb_id, user_id) DO UPDATE SET role = #{role}, granted_by = #{grantedBy}
